  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font);
  font-size: 17px;
  line-height: 1.6;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 { line-height: 1.2; margin: 0 0 .5em; letter-spacing: -0.01em; }
h1 { font-size: clamp(2.1rem, 4.5vw, 3.3rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.6rem, 3vw, 2.2rem); text-align: center; }
h3 { font-size: 1.15rem; }
p { margin: 0 0 1em; }
a { color: var(--brand); }

:focus-visible { outline: 3px solid var(--brand); outline-offset: 3px; border-radius: 6px; }

.container { width: min(1120px, 100% - 40px); margin-inline: auto; }

.visually-hidden {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 12px; top: -48px; z-index: 100;
  background: var(--ink); color: #fff; padding: 8px 14px; border-radius: 8px;
  text-decoration: none;
}
.skip-link:focus { top: 12px; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 13px 22px; border-radius: 10px; border: 1.5px solid transparent;
  font: inherit; font-weight: 600; font-size: 1rem; text-decoration: none;
  cursor: pointer; transition: background-color .15s ease, border-color .15s ease, transform .15s ease;
}
.btn-primary { background: var(--brand); color: #fff; }
.btn-primary:hover { background: var(--brand-dark); transform: translateY(-1px); }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--line); }
.btn-ghost:hover { border-color: var(--ink-soft); }
.btn-small { padding: 8px 16px; font-size: .95rem; background: var(--brand); color: #fff; }
.btn-small:hover { background: var(--brand-dark); }
.btn-block { width: 100%; }

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(251, 250, 247, .9);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner { display: flex; align-items: center; justify-content: space-between; height: 64px; }
.logo { display: inline-flex; align-items: center; gap: 10px; font-weight: 700; font-size: 1.15rem; color: var(--ink); text-decoration: none; }
.logo-mark {
  width: 26px; height: 26px; border-radius: 8px; background: var(--brand); position: relative;
}
.logo-mark::after {
  content: ""; position: absolute; left: 8px; top: 5px; width: 6px; height: 11px;
  border: solid #fff; border-width: 0 2.5px 2.5px 0; transform: rotate(45deg);
}
.site-nav { display: flex; align-items: center; gap: 28px; }
.site-nav a:not(.btn) { color: var(--ink-soft); text-decoration: none; font-weight: 500; }
.site-nav a:not(.btn):hover { color: var(--ink); }

.nav-toggle { display: none; background: none; border: 0; width: 44px; height: 44px; cursor: pointer; position: relative; }
.nav-toggle-bar, .nav-toggle-bar::before, .nav-toggle-bar::after {
  position: absolute; left: 11px; width: 22px; height: 2px; background: var(--ink); content: "";
  transition: transform .2s ease;
}
.nav-toggle-bar { top: 21px; }
.nav-toggle-bar::before { left: 0; top: -7px; }
.nav-toggle-bar::after { left: 0; top: 7px; }

/* Hero */
.hero { padding: 80px 0 96px; }
.hero-inner { display: grid; grid-template-columns: 1.1fr 1fr; gap: 64px; align-items: center; }
.eyebrow { color: var(--brand); font-weight: 600; font-size: .95rem; margin-bottom: 14px; }
.lede { font-size: 1.15rem; color: var(--ink-soft); max-width: 34em; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin: 28px 0 14px; }
.fine-print { font-size: .9rem; color: var(--ink-soft); }

.hero-demo { margin: 0; display: grid; gap: 12px; }
.demo-card {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 20px 22px; box-shadow: var(--shadow); font-size: .95rem;
}
.demo-card p { margin-bottom: .5em; }
.demo-card p:last-child { margin-bottom: 0; }
.demo-transcript { color: var(--ink-soft); }
.demo-transcript strong { color: var(--ink); }
.demo-label { font-size: .8rem; font-weight: 600; text-transform: uppercase; letter-spacing: .06em; color: var(--ink-soft); }
.demo-arrow { text-align: center; color: var(--brand); font-size: 1.3rem; line-height: 1; }
.demo-actions { border-color: #cfd4fa; }
.demo-actions ul { list-style: none; margin: 0; padding: 0; }
.demo-actions li {
  display: grid; grid-template-columns: auto 1fr auto; gap: 12px; align-items: center;
  padding: 10px 0; border-top: 1px solid var(--line);
}
.demo-actions li:first-child { border-top: 0; padding-top: 4px; }
.check { width: 18px; height: 18px; border-radius: 5px; border: 2px solid var(--accent); }
.meta { font-size: .82rem; color: var(--ink-soft); background: var(--brand-tint); padding: 2px 9px; border-radius: 999px; white-space: nowrap; }

/* Features */
.features { padding: 88px 0; background: var(--surface); border-block: 1px solid var(--line); }
.feature-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 28px; margin-top: 48px; }
.feature p { color: var(--ink-soft); margin: 0; }
.feature-icon {
  width: 40px; height: 40px; border-radius: 10px; display: grid; place-items: center;
  background: var(--brand-tint); color: var(--brand); font-weight: 700; margin-bottom: 16px;
}

/* Testimonials */
.testimonials { padding: 88px 0; }
.quote-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 28px; margin-top: 48px; }
.quote {
  margin: 0; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 32px; box-shadow: var(--shadow); display: flex; flex-direction: column; justify-content: space-between;
}
.quote blockquote { margin: 0 0 24px; font-size: 1.1rem; }
.quote blockquote p { margin: 0; }
.quote figcaption { display: flex; align-items: center; gap: 14px; font-size: .95rem; color: var(--ink-soft); }
.quote figcaption strong { color: var(--ink); }
.avatar {
  flex: none; width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center;
  background: var(--ink); color: #fff; font-weight: 600; font-size: .85rem;
}

/* Pricing */
.pricing { padding: 88px 0 104px; background: var(--surface); border-top: 1px solid var(--line); }
.section-lede { text-align: center; color: var(--ink-soft); }
.billing-toggle {
  display: flex; width: max-content; margin: 28px auto 40px; padding: 4px;
  background: var(--bg); border: 1px solid var(--line); border-radius: 999px;
}
.toggle-option {
  font: inherit; font-weight: 600; font-size: .95rem; border: 0; background: none; color: var(--ink-soft);
  padding: 8px 18px; border-radius: 999px; cursor: pointer;
}
.toggle-option.is-active { background: var(--surface); color: var(--ink); box-shadow: 0 1px 3px rgba(0, 0, 0, .1); }
.save { color: var(--accent); font-size: .85rem; margin-left: 4px; }

.plan-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 380px)); justify-content: center; gap: 28px; }
.plan {
  position: relative; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 32px; display: flex; flex-direction: column;
}
.plan-featured { border: 2px solid var(--brand); box-shadow: var(--shadow); }
.badge {
  position: absolute; top: -13px; left: 32px; margin: 0;
  background: var(--brand); color: #fff; font-size: .8rem; font-weight: 600; padding: 3px 12px; border-radius: 999px;
}
.plan-desc { color: var(--ink-soft); }
.price { margin: 8px 0 4px; display: flex; align-items: baseline; gap: 6px; }
.amount { font-size: 2.6rem; font-weight: 700; letter-spacing: -0.02em; }
.per { color: var(--ink-soft); }
.billing-note { font-size: .9rem; color: var(--ink-soft); min-height: 1.5em; }
.plan-list { list-style: none; padding: 0; margin: 16px 0 28px; flex: 1; }
.plan-list li { position: relative; padding: 6px 0 6px 28px; }
.plan-list li::before {
  content: ""; position: absolute; left: 4px; top: 12px; width: 6px; height: 11px;
  border: solid var(--accent); border-width: 0 2px 2px 0; transform: rotate(45deg);
}

/* Footer */
.site-footer { padding: 32px 0; border-top: 1px solid var(--line); color: var(--ink-soft); font-size: .95rem; }
.footer-inner { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; }
.footer-inner p { margin: 0; }
.footer-inner nav { display: flex; gap: 24px; }
.footer-inner a { color: var(--ink-soft); text-decoration: none; }
.footer-inner a:hover { color: var(--ink); }

/* Responsive */
@media (max-width: 960px) {
  .hero-inner { grid-template-columns: 1fr; gap: 48px; }
  .feature-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 720px) {
  .hero { padding: 48px 0 64px; }
  .features, .testimonials, .pricing { padding: 64px 0; }
  .feature-grid, .quote-grid { grid-template-columns: 1fr; }
  .plan-grid { grid-template-columns: 1fr; }
  .quote { padding: 24px; }

  .nav-toggle { display: block; }
  .site-nav {
    display: none; position: absolute; top: 64px; left: 0; right: 0;
    flex-direction: column; align-items: stretch; gap: 0; padding: 8px 20px 20px;
    background: var(--bg); border-bottom: 1px solid var(--line);
  }
  .site-nav.is-open { display: flex; }
  .site-nav a:not(.btn) { padding: 12px 0; border-bottom: 1px solid var(--line); }
  .site-nav .btn { margin-top: 16px; padding: 12px; }
  .nav-toggle[aria-expanded="true"] .nav-toggle-bar { background: transparent; }
  .nav-toggle[aria-expanded="true"] .nav-toggle-bar::before { transform: translateY(7px) rotate(45deg); }
  .nav-toggle[aria-expanded="true"] .nav-toggle-bar::after { transform: translateY(-7px) rotate(-45deg); }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition: none !important; }
  .btn-primary:hover { transform: none; }
}

